INSERT INTO offerings (id, specialist_id, name, description, duration_minutes, price_amount, currency, is_active) VALUES
  ('d602f67e-b08d-5448-ad9a-20c5caf99577', 'b346bb39-7b81-5716-9ef7-54968df362b1', 'Home workout program', 'A four-week program that needs no equipment.', 30, 65.00, 'EUR', 't'),
  ('df5a8e53-a67d-5aef-bef3-7017ed5dd5d9', 'b346bb39-7b81-5716-9ef7-54968df362b1', 'Personal training', 'Full-body training session adapted to your level, with a plan for the days between sessions.', 60, 40.00, 'USD', 't'),
  ('0b5b736a-0276-5117-8d78-395db6f51b4a', 'b346bb39-7b81-5716-9ef7-54968df362b1', 'Running technique analysis', 'Video-based analysis of your running form with drills to reduce injury risk and improve pace.', 45, 45.00, 'EUR', 't'),
  ('39fb65ba-3dd1-5ec9-90c0-6a634c359280', '1f50784f-94fb-5e7a-bf6d-170e161c9b66', 'LinkedIn profile makeover', 'Headline, summary and experience sections rewritten to attract recruiters in your field.', 45, 45.00, 'EUR', 't'),
  ('f9af8500-844f-5d8b-bcf5-7414c285ce49', '1f50784f-94fb-5e7a-bf6d-170e161c9b66', 'Portfolio feedback', 'Honest, structured feedback on your portfolio: what to keep, what to cut and how to present your best work first. Includes a short written summary after the call.', 60, 55.00, 'EUR', 't'),
  ('4482f2fe-7f1b-542a-b43e-7e1eea42853a', '1f50784f-94fb-5e7a-bf6d-170e161c9b66', 'Resume review', 'A focused pass over your CV with concrete rewrites.', 30, 35.00, 'EUR', 't'),
  ('c720eb86-8a82-57b9-8853-8433d35a3d17', '720147bc-07fe-5488-a382-5a0a0dad25b3', 'Guided meditation', 'A calm guided session to reduce stress and improve focus, suitable for complete beginners.', 30, 20.00, 'EUR', 't'),
  ('852dcd8e-7ec2-5108-9760-2a8e00bd87e8', '720147bc-07fe-5488-a382-5a0a0dad25b3', 'Yoga for beginners', 'Gentle introduction to the basic poses, breathing and alignment.', 60, 25.00, 'EUR', 't'),
  ('a0b2a760-5b04-57f8-aacf-54bc6e5f786a', '9fae8b51-d5e4-5d91-879d-0c1f203e712d', 'Code review session', 'Live review of your pull request or side project with suggestions on structure, naming and tests.', 60, 70.00, 'EUR', 't'),
  ('f002e77f-a0d2-5e02-bdd0-304e0f920c08', '9fae8b51-d5e4-5d91-879d-0c1f203e712d', 'Mock interview', 'Realistic technical and behavioral interview followed by a detailed debrief.', 45, 50.00, 'EUR', 't'),
  ('22686905-1e75-51d0-9bdd-a404825380b5', '9fae8b51-d5e4-5d91-879d-0c1f203e712d', 'System design coaching', 'Walk through a system design problem end to end and learn a repeatable way to structure your answers.', 90, 110.00, 'USD', 't'),
  ('683201b4-974d-54c4-814c-768977db24e7', '443b2c15-36b3-520f-97c1-591c8a9d27a5', 'Meal prep basics', 'Learn to prepare five days of meals in one afternoon.', 45, 30.00, 'EUR', 't'),
  ('84d5fb83-54f6-5461-bb99-4bf01e76a870', '443b2c15-36b3-520f-97c1-591c8a9d27a5', 'Nutrition plan', 'A personal weekly nutrition plan based on your goals, schedule and preferences, with shopping lists and easy substitutions. Includes one follow-up message within a week.', 90, 90.00, 'EUR', 't'),
  ('4587ef86-e17b-5928-a576-46055e574760', 'ce9b7eb8-a861-59fd-b73f-70b086723f9c', 'Business English', 'Prepare for meetings, presentations and emails in English with role plays based on your real work situations.', 60, 35.00, 'EUR', 't'),
  ('2e5ca77f-9d8e-5163-b363-b1fea5477f4d', 'ce9b7eb8-a861-59fd-b73f-70b086723f9c', 'English conversation practice', 'Relaxed one-to-one conversation with gentle corrections and a short vocabulary list afterwards.', 45, 20.00, 'EUR', 't'),
  ('bdc29097-f7ab-545b-a539-b7215147af62', 'ce9b7eb8-a861-59fd-b73f-70b086723f9c', 'IELTS speaking preparation', 'Timed practice of all three parts of the speaking test, scoring against the official criteria and a personal improvement plan for the weeks before your exam.', 90, 60.00, 'EUR', 't')
ON CONFLICT DO NOTHING;

